import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"FaultDeck Desktop UI — Design","description":"","frontmatter":{},"headers":[],"relativePath":"design/desktop-ui.md","filePath":"design/desktop-ui.md"}`),a={name:`design/desktop-ui.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="faultdeck-desktop-ui-—-design" tabindex="-1">FaultDeck Desktop UI — Design <a class="header-anchor" href="#faultdeck-desktop-ui-—-design" aria-label="Permalink to “FaultDeck Desktop UI — Design”">​</a></h1><p>Date: 2026-11-08 · Status: approved for implementation · Shell: Tauri (Rust + WebView)</p><h2 id="_1-decision" tabindex="-1">1. Decision <a class="header-anchor" href="#_1-decision" aria-label="Permalink to “1. Decision”">​</a></h2><p><strong>Tauri 2</strong> desktop shell (native window + WebView), Rust backend calls the FaultDeck coordinator directly over the existing TCP wire protocol — no extra HTTP layer, no Node bridge. Chosen over Electron (smaller, Rust-native, no Node) and over a pure web dashboard (no installer — the user requires setup.exe/dmg installers in the nightly matrix).</p><p>Linux build deps confirmed present: webkit2gtk-4.1 (2.52.6), gtk+-3.0 (3.24.52), node 24 / pnpm 12.</p><h2 id="_2-architecture" tabindex="-1">2. Architecture <a class="header-anchor" href="#_2-architecture" aria-label="Permalink to “2. Architecture”">​</a></h2><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>faultdeck-desktop/  (Tauri app, added to the workspace as a crate)</span></span>
<span class="line"><span>  src-tauri/  (Rust): tauri commands -&gt; coordinator wire client</span></span>
<span class="line"><span>      └ coordinator.rs   # TcpStream client speaking WireMessage/AgentCommand</span></span>
<span class="line"><span>  ui/         (frontend, pnpm + Vite + vanilla TS)</span></span>
<span class="line"><span>      └ src/  views + a tiny wire-client (fetch -&gt; tauri invoke)</span></span></code></pre></div><p>The Rust side is the <strong>only</strong> thing that talks to the coordinator. The frontend calls <code>invoke(&quot;coordinator_list&quot;)</code> / <code>invoke(&quot;coordinator_inject&quot;, …)</code> / <code>invoke(&quot;coordinator_rollback&quot;, …)</code>; those run in Rust, open a TCP stream, send the JSON wire message, await the framed response.</p><h2 id="_3-wire-contract-verbatim-from-crates-coordinator-src-lib-rs" tabindex="-1">3. Wire contract (verbatim from crates/coordinator/src/lib.rs) <a class="header-anchor" href="#_3-wire-contract-verbatim-from-crates-coordinator-src-lib-rs" aria-label="Permalink to “3. Wire contract (verbatim from crates/coordinator/src/lib.rs)”">​</a></h2><p>Every request is one <code>WireMessage</code> line, newline-framed, UTF-8 JSON:</p><div class="language-json" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;optional&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;cmd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;list_agents&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;optional&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;cmd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;inject&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;agent_id&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;injection&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;fault&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;latency&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;milliseconds&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;destination&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;10.0.0.0/24&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;destination_port&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}}}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;optional&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;cmd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rollback&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;agent_id&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;optional&gt;,&quot;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">command</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;:{&quot;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">cmd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;:&quot;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">fetch_report</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;,&quot;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;:&quot;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">&lt;agent_id&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;,&quot;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">scenario_hash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;:&quot;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">&lt;hash&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;}}</span></span></code></pre></div><p>Responses are <code>AgentResponse</code> tagged on <code>status</code>: <code>ok | error | registered | queued | agents{agents,available} | report{report}</code>.</p><p>The <code>agents</code> response drives the fleet view: <code>{ &quot;agents&quot;:[{&quot;id&quot;,&quot;capabilities&quot;,&quot;last_seen_ms&quot;,&quot;online&quot;}], &quot;available&quot;:[...] }</code>.</p><p>The <code>report</code> response carries a <code>RunReport</code>: <code>{scenario_name, scenario_yaml, scenario_hash, injected_at_ms, rolled_back_at_ms, events[], restore_evidence[], external_assertions[], replay_command}</code>.</p><p>Fault spec shapes (serde tag <code>kind</code>): <code>latency{milliseconds}</code>, <code>loss{percent}</code>, <code>disconnect{all_traffic}</code>. Target: <code>{source?, destination?, destination_port?}</code> (IpNet strings).</p><h2 id="_4-views" tabindex="-1">4. Views <a class="header-anchor" href="#_4-views" aria-label="Permalink to “4. Views”">​</a></h2><h3 id="_4-1-fleet-default" tabindex="-1">4.1 Fleet (default) <a class="header-anchor" href="#_4-1-fleet-default" aria-label="Permalink to “4.1 Fleet (default)”">​</a></h3><ul><li>Card per agent: id, online dot, capabilities chips, last_seen.</li><li>Header: coordinator host/port (editable), token (optional), <strong>Connect</strong>, <strong>Refresh</strong>.</li><li>Per-card actions: <strong>Inject</strong> (opens 4.2), <strong>Rollback</strong> (confirm; disabled when nothing applied).</li><li>Applied-fault badge: agent id → scenario hash from <code>applied</code> state (shown when known).</li></ul><h3 id="_4-2-inject-dialog" tabindex="-1">4.2 Inject dialog <a class="header-anchor" href="#_4-2-inject-dialog" aria-label="Permalink to “4.2 Inject dialog”">​</a></h3><ul><li>Fault kind segmented control: Latency / Loss / Disconnect. <ul><li>Latency: <code>milliseconds</code> (1..86,400,000).</li><li>Loss: <code>percent</code> (0 &lt; p ≤ 100).</li><li>Disconnect: <code>all_traffic</code> toggle.</li></ul></li><li>Target: source (optional IpNet), destination (optional IpNet), destination_port (optional 1..65535). At least one of destination / destination_port required (UI validation).</li><li><strong>Apply</strong> sends <code>inject</code>; shows the agent response (ok / queued / error).</li></ul><h3 id="_4-3-report" tabindex="-1">4.3 Report <a class="header-anchor" href="#_4-3-report" aria-label="Permalink to “4.3 Report”">​</a></h3><ul><li>List of archived reports (scenario_hash → title), latest first.</li><li>Selected report: scenario YAML (monospace), injected/rolled-back timestamps, event timeline, restore-evidence table (check/passed/detail), external assertions (pass/fail), replay command with a <strong>Copy</strong> button.</li></ul><h3 id="_4-4-settings-persisted-in-localstorage" tabindex="-1">4.4 Settings (persisted in localStorage) <a class="header-anchor" href="#_4-4-settings-persisted-in-localstorage" aria-label="Permalink to “4.4 Settings (persisted in localStorage)”">​</a></h3><ul><li>Coordinator host/port, token, heartbeat timeout.</li></ul><h2 id="_5-error-edge-handling" tabindex="-1">5. Error &amp; edge handling <a class="header-anchor" href="#_5-error-edge-handling" aria-label="Permalink to “5. Error &amp; edge handling”">​</a></h2><ul><li>Coordinator unreachable: inline banner &quot;coordinator unreachable at host:port&quot; + retry; never a blank screen.</li><li>Empty fleet: empty-state panel &quot;no agents registered — start <code>faultdeck-agent</code> on the target and it appears here.&quot;</li><li>Inject validation errors render under the field; the backend <code>error</code> response renders in the dialog footer.</li><li>Long-running dispatch shows a spinner; results land in the event timeline.</li></ul><h2 id="_6-acceptance" tabindex="-1">6. Acceptance <a class="header-anchor" href="#_6-acceptance" aria-label="Permalink to “6. Acceptance”">​</a></h2><ol><li><code>cargo build -p faultdeck-desktop</code> green; <code>tauri build</code> produces the platform installer.</li><li>Against a live coordinator + one agent: connect → agent appears online → inject latency → applied badge → rollback → badge clears.</li><li>Report list loads a real <code>RunReport</code>; replay command copies.</li><li>All above exercised in the headless check (coordinator + agent on 127.0.0.1 ephemeral ports) as part of the nightly CI smoke.</li></ol>`,28)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};